NewtonDistanceInterval newton_input_distance_interval(
    const NewtonAudit& audit,const NewtonInputErrorBounds& bounds,double budget) {
  NewtonDistanceInterval out;
  out.status=bounds.status;
  if(bounds.status!=NewtonAccuracyStatus::Available) return out;
  if(!(bounds.curvature_lower_bound>0)) {
    out.status=NewtonAccuracyStatus::IllConditioned; return out;
  }
  if(audit.derivatives.metric_kind==NewtonMetricKind::Sandwich)
    return newton_metric_distance_interval(audit.metric_factor_system,
        audit.derivatives.metric_score_residual,bounds.matrix,bounds.vector,budget);
  return newton_hessian_distance_interval(audit.system,audit.geometry.reduced_gradient,
      bounds.matrix,bounds.vector,budget);
}
